package com.quincaisoft.platformcontrol.web;
import com.quincaisoft.platformcontrol.api.PlatformGovernanceService;import com.quincaisoft.shared.TenantLifecyclePolicy;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController public class PlatformGovernanceController{
 private final PlatformGovernanceService service;public PlatformGovernanceController(PlatformGovernanceService service){this.service=service;}
 @GetMapping("/api/v1/support/grants") @PreAuthorize("hasAnyAuthority('support:read','SCOPE_support:read')")public List<PlatformGovernanceService.Grant> merchantGrants(){return service.merchantGrants();}
 @PostMapping("/api/v1/support/grants") @PreAuthorize("hasAnyAuthority('support:write','SCOPE_support:write')")public PlatformGovernanceService.Grant consent(@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID correlation,@RequestBody PlatformGovernanceService.Consent input){same(operation,input.operationId());return service.consent(input);}
 @PostMapping("/api/v1/support/grants/{id}/revoke") @PreAuthorize("hasAnyAuthority('support:write','SCOPE_support:write')")public PlatformGovernanceService.Grant revoke(@PathVariable UUID id,@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID correlation,@RequestBody PlatformGovernanceService.Command input){same(operation,input.operationId());return service.revoke(id,input);}
 @GetMapping("/admin/governance/support-grants") @PreAuthorize("hasAuthority('SCOPE_platform:support:read')")public List<PlatformGovernanceService.Grant> platformGrants(){return service.platformGrants();}
 @PostMapping("/admin/governance/support-grants/{id}/approve") @PreAuthorize("hasAuthority('SCOPE_platform:support:approve')")public PlatformGovernanceService.Grant approveGrant(@PathVariable UUID id,@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID correlation,@RequestBody PlatformGovernanceService.Command input){same(operation,input.operationId());return service.approveGrant(id,input);}
 @GetMapping("/admin/governance/support-grants/{id}/diagnostics") @PreAuthorize("hasAuthority('SCOPE_platform:support:read')")public PlatformGovernanceService.Diagnostics diagnostics(@PathVariable UUID id,@RequestHeader("X-Request-ID")UUID correlation){return service.diagnostics(id,correlation);}
 @GetMapping("/admin/governance/tenants/{tenantId}/status") @PreAuthorize("hasAuthority('SCOPE_platform:governance:read')")public TenantLifecyclePolicy.State status(@PathVariable UUID tenantId){return service.tenantState(tenantId);}
 @GetMapping("/admin/governance/tenants/{tenantId}/legal-holds") @PreAuthorize("hasAuthority('SCOPE_platform:governance:read')")public List<PlatformGovernanceService.Hold> holds(@PathVariable UUID tenantId){return service.holds(tenantId);}
 @GetMapping("/admin/governance/requests") @PreAuthorize("hasAuthority('SCOPE_platform:governance:read')")public List<PlatformGovernanceService.Review> requests(@RequestParam UUID tenantId){return service.requests(tenantId);}
 @PostMapping("/admin/governance/tenants/{tenantId}/requests") @PreAuthorize("hasAuthority('SCOPE_platform:governance:write')")public PlatformGovernanceService.Review request(@PathVariable UUID tenantId,@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID correlation,@RequestBody PlatformGovernanceService.Request input){same(operation,input.operationId());return service.request(tenantId,input);}
 @PostMapping("/admin/governance/requests/{id}/approve") @PreAuthorize("hasAuthority('SCOPE_platform:governance:approve')")public PlatformGovernanceService.Review approve(@PathVariable UUID id,@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID correlation,@RequestBody PlatformGovernanceService.Command input){same(operation,input.operationId());return service.approve(id,input);}
 private static void same(UUID header,UUID body){if(!header.equals(body))throw new IllegalArgumentException("Operation mismatch");}
}
